package com.foamplayer.app.ui.screens.queue

import com.foamplayer.app.data.db.entities.TrackEntity

/**
 * An item in the upcoming queue list.
 *  - [entryId]: unique id generated by the engine.
 *  - [absoluteIndex]: position in the underlying queue, for diagnostics only;
 *    mutations go through the engine by entry id so a snapshot never goes stale
 *    mid-gesture.
 *  - [isAuxiliary]: rendered translucent, taken from the same snapshot as the id.
 *  - [isFreshFromRefill]: row appended by the latest auxiliary refill.
 */
data class QueueItem(
    val entryId: Long,
    val absoluteIndex: Int,
    val track: TrackEntity,
    val isAuxiliary: Boolean,
    val isFreshFromRefill: Boolean
)